import{_ as a,o as e,c as l,ah as s}from"./chunks/framework.CPHJ30oF.js";const o=JSON.parse('{"title":"09-如何将镜像体积缩小90%-多阶段构建与Alpine镜像调优指南","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"为什么要关注镜像体积","slug":"为什么要关注镜像体积","link":"#为什么要关注镜像体积","children":[]},{"level":2,"title":"1. 多阶段构建：把构建环境和运行环境分离","slug":"_1-多阶段构建-把构建环境和运行环境分离","link":"#_1-多阶段构建-把构建环境和运行环境分离","children":[]},{"level":2,"title":"2. 使用轻量基础镜像（Alpine）","slug":"_2-使用轻量基础镜像-alpine","link":"#_2-使用轻量基础镜像-alpine","children":[]},{"level":2,"title":"3. 其他常见瘦身策略","slug":"_3-其他常见瘦身策略","link":"#_3-其他常见瘦身策略","children":[{"level":3,"title":"3.1 减少镜像层数","slug":"_3-1-减少镜像层数","link":"#_3-1-减少镜像层数","children":[]},{"level":3,"title":"3.2 清理临时文件","slug":"_3-2-清理临时文件","link":"#_3-2-清理临时文件","children":[]},{"level":3,"title":"3.3 使用 .dockerignore","slug":"_3-3-使用-dockerignore","link":"#_3-3-使用-dockerignore","children":[]},{"level":3,"title":"3.4 只复制必要文件","slug":"_3-4-只复制必要文件","link":"#_3-4-只复制必要文件","children":[]}]},{"level":2,"title":"4. 体积优化与稳定性之间的平衡","slug":"_4-体积优化与稳定性之间的平衡","link":"#_4-体积优化与稳定性之间的平衡","children":[]},{"level":2,"title":"5. 实战建议","slug":"_5-实战建议","link":"#_5-实战建议","children":[]},{"level":2,"title":"6. 常见误区","slug":"_6-常见误区","link":"#_6-常见误区","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"docker/09-如何将镜像体积缩小90%-多阶段构建与Alpine镜像调优指南.md","filePath":"docker/09-如何将镜像体积缩小90%-多阶段构建与Alpine镜像调优指南.md"}'),n={name:"docker/09-如何将镜像体积缩小90%-多阶段构建与Alpine镜像调优指南.md"};function h(t,i,p,d,r,k){return e(),l("div",null,[...i[0]||(i[0]=[s(`<h1 id="_09-如何将镜像体积缩小90-多阶段构建与alpine镜像调优指南" tabindex="-1">09-如何将镜像体积缩小90%-多阶段构建与Alpine镜像调优指南 <a class="header-anchor" href="#_09-如何将镜像体积缩小90-多阶段构建与alpine镜像调优指南" aria-label="Permalink to “09-如何将镜像体积缩小90%-多阶段构建与Alpine镜像调优指南”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>镜像体积直接影响构建速度、拉取时间、部署效率与运行成本。一个过大的镜像会让 CI 变慢、部署变慢、容器启动变慢。</p><p>本篇文章聚焦两条最实用的优化路径：多阶段构建与 Alpine 轻量镜像，同时兼顾可维护性和稳定性。</p><h2 id="为什么要关注镜像体积" tabindex="-1">为什么要关注镜像体积 <a class="header-anchor" href="#为什么要关注镜像体积" aria-label="Permalink to “为什么要关注镜像体积”">​</a></h2><p>镜像体积过大带来的问题：</p><ul><li>网络传输慢；</li><li>CI 构建与缓存效率低；</li><li>容器启动和部署延迟增加；</li><li>存储成本上升；</li><li>安全扫描范围扩大。</li></ul><p>优化镜像不是为了“炫耀数字”，而是为了提升整个交付链路的效率。</p><h2 id="_1-多阶段构建-把构建环境和运行环境分离" tabindex="-1">1. 多阶段构建：把构建环境和运行环境分离 <a class="header-anchor" href="#_1-多阶段构建-把构建环境和运行环境分离" aria-label="Permalink to “1. 多阶段构建：把构建环境和运行环境分离”">​</a></h2><p>多阶段构建允许你在一个 Dockerfile 中使用多个阶段。前一个阶段负责构建、安装开发依赖，最终阶段只保留运行时所需文件。</p><p>示例：</p><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node:20-alpine </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> builder</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /app</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package*.json ./</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm install</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> . .</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm run build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node:20-alpine</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /app</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --from=builder /app/package*.json ./</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --from=builder /app/node_modules ./node_modules</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --from=builder /app/dist ./dist</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dist/index.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>这样最终镜像中不会出现构建工具、源码编译缓存和临时文件。</p><h2 id="_2-使用轻量基础镜像-alpine" tabindex="-1">2. 使用轻量基础镜像（Alpine） <a class="header-anchor" href="#_2-使用轻量基础镜像-alpine" aria-label="Permalink to “2. 使用轻量基础镜像（Alpine）”">​</a></h2><p><code>alpine</code> 镜像非常小，适合对体积敏感的场景。但它也可能带来兼容性问题，例如某些二进制依赖需要 <code>glibc</code> 或额外包。</p><p>示例：</p><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> python:3.12-alpine</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> apk add --no-cache build-base libffi-dev</span></span></code></pre></div><p>当你选择 Alpine 时，务必要测试运行时行为，尤其是依赖编译、动态链接库和 shell 命令。</p><h2 id="_3-其他常见瘦身策略" tabindex="-1">3. 其他常见瘦身策略 <a class="header-anchor" href="#_3-其他常见瘦身策略" aria-label="Permalink to “3. 其他常见瘦身策略”">​</a></h2><h3 id="_3-1-减少镜像层数" tabindex="-1">3.1 减少镜像层数 <a class="header-anchor" href="#_3-1-减少镜像层数" aria-label="Permalink to “3.1 减少镜像层数”">​</a></h3><p>每个 <code>RUN</code>、<code>COPY</code>、<code>ADD</code> 指令都会产生一层。合理合并命令能减少层数，但不要牺牲可读性。</p><h3 id="_3-2-清理临时文件" tabindex="-1">3.2 清理临时文件 <a class="header-anchor" href="#_3-2-清理临时文件" aria-label="Permalink to “3.2 清理临时文件”">​</a></h3><p>安装依赖时，避免留下缓存：</p><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> apk add --no-cache ... &amp;&amp; rm -rf /var/cache/apk/*</span></span></code></pre></div><h3 id="_3-3-使用-dockerignore" tabindex="-1">3.3 使用 <code>.dockerignore</code> <a class="header-anchor" href="#_3-3-使用-dockerignore" aria-label="Permalink to “3.3 使用 .dockerignore”">​</a></h3><p>把不需要的文件从上下文中排除，例如 <code>node_modules</code>、日志、IDE 配置文件。</p><h3 id="_3-4-只复制必要文件" tabindex="-1">3.4 只复制必要文件 <a class="header-anchor" href="#_3-4-只复制必要文件" aria-label="Permalink to “3.4 只复制必要文件”">​</a></h3><p>不要 <code>COPY . .</code>，而应先复制依赖清单，再复制源代码，这样能提高缓存命中率。</p><h2 id="_4-体积优化与稳定性之间的平衡" tabindex="-1">4. 体积优化与稳定性之间的平衡 <a class="header-anchor" href="#_4-体积优化与稳定性之间的平衡" aria-label="Permalink to “4. 体积优化与稳定性之间的平衡”">​</a></h2><ul><li>不是每个镜像都必须用 Alpine。对于复杂依赖，<code>slim</code> 或官方基础镜像可能更稳定。</li><li>不是所有步骤都要压缩成一行。保持 Dockerfile 可读性，便于长期维护。</li><li>先保证镜像可运行，再做瘦身优化。</li></ul><h2 id="_5-实战建议" tabindex="-1">5. 实战建议 <a class="header-anchor" href="#_5-实战建议" aria-label="Permalink to “5. 实战建议”">​</a></h2><ol><li>先使用多阶段构建；</li><li>再评估是否适合 Alpine；</li><li>用 <code>docker history</code> 和 <code>docker images --format</code> 分析镜像层；</li><li>使用 <code>dive</code>、<code>docker-slim</code> 等工具检查体积来源；</li><li>在 CI 中持续监控镜像体积变化。</li></ol><h2 id="_6-常见误区" tabindex="-1">6. 常见误区 <a class="header-anchor" href="#_6-常见误区" aria-label="Permalink to “6. 常见误区”">​</a></h2><ul><li>误认为镜像体积越小越好。可维护性与稳定性同样重要。</li><li>误把 <code>alpine</code> 作为默认选择。选择应基于依赖兼容性。</li><li>误以为删除文件即可减小体积。只删可写层文件足够，但镜像层仍然保留历史。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>镜像优化是一个“先结构化、后细化”的过程：先用多阶段构建分离构建与运行阶段，再用合适基础镜像和上下文控制压缩体积。这样你才能把“体积小”变成“交付快、部署稳、运维好”的真实收益。</p>`,36)])])}const g=a(n,[["render",h]]);export{o as __pageData,g as default};
